#!/usr/bin/env bash
# The ElastiCORE plugin's hooks. They keep an agent on the DSL side of an
# ElastiCORE project: a generated file is changed through the YAML under
# src/main/resources/blueprint/<domain>/, and a DSL change is generated and
# compiled before the agent says it is done.
#
#   pre-edit   PreToolUse  Edit|Write|MultiEdit  refuse an edit to a file the generator rewrites
#   pre-bash   PreToolUse  Bash                  refuse a Gradle run with -Pforce
#   post-edit  PostToolUse Edit|Write|MultiEdit  after a DSL edit, say what to run before finishing
#   post-bash  PostToolUse Bash                  after a Gradle run, pass on what the generator said
#   stop       Stop                              do not finish while a DSL change has not been built
#
# Bash and POSIX tools only: Claude Code runs hooks with sh on macOS and Linux
# and with Git Bash on Windows. Anything unexpected ends in exit 0 or 1, which
# lets the action go ahead - a broken hook never blocks the user's work.
#
# ELASTICORE_ALLOW_GENERATED_EDITS=1 lets edits to generated files through;
# ELASTICORE_ALLOW_FORCE=1 lets -Pforce through.

set -u

event="${1:-}"
input="$(cat)" || exit 0

# The raw value of a JSON string field, still escaped. Claude Code sends one
# line of JSON; a key inside another string value is escaped (\"key\") and is
# not matched.
json_string() {
    printf '%s' "$input" | sed -nE 's/.*"'"$1"'"[[:space:]]*:[[:space:]]*"((\\.|[^"\\])*)".*/\1/p' | head -n 1
}

# Whether a JSON boolean field is true. An escaped key inside a string value
# does not match.
json_true() {
    case "$input" in
        *"\"$1\":true"* | *"\"$1\": true"*) return 0 ;;
    esac
    return 1
}

# The edited file. Windows paths arrive as C:\\dir\\file; Git Bash reads them
# with forward slashes, and slashes keep them safe inside the JSON written below.
file_path() {
    json_string file_path | sed 's#\\\\#/#g'
}

# Who owns a file, by the rules the generator applies to it.
#   none         no such file yet
#   hand         not written by ElastiCORE
#   owned        "// Initially generated by ElastiCORE;" near the top: the developer's
#   block        generated, with a preserved block that survives regeneration
#   managed      generated: rewritten from the DSL, skipped once edited by hand
#   regenerated  written again on every generation and with no //ecd: line -
#                schema.yml, the copied guides, the default messages file
# The generator looks for the ownership line within 200 characters after line
# one; 600 bytes here only errs on the side of letting an edit through.
classify() {
    [ -f "$1" ] || { echo none; return; }
    first="$(head -n 1 -- "$1" 2>/dev/null | tr -d '\r\357\273\277')"
    case "$first" in
        //ecd:*)
            if head -c 600 -- "$1" 2>/dev/null | grep -q -F -e '// Initially generated by ElastiCORE;'; then
                echo owned
            elif grep -q -F -e '// !----------' -- "$1" 2>/dev/null; then
                echo block
            else
                echo managed
            fi
            return
            ;;
    esac
    case "$1" in
        */src/main/resources/blueprint/schema.yml | */src/main/resources/blueprint/semantic_model.yml | \
        */src/main/resources/blueprint/context-map.md | */src/main/resources/blueprint/elasticore-*.md)
            echo regenerated
            return
            ;;
        # A translation starts as a copy of the default messages file, header
        # included, but it is the developer's.
        *-messages_*.properties)
            echo hand
            return
            ;;
    esac
    if head -n 5 -- "$1" 2>/dev/null | grep -q -F -e 'Generated by ElastiCORE'; then
        echo regenerated
    else
        echo hand
    fi
}

# The model: YAML in a domain folder under the blueprint. Files in the
# blueprint root (schema.yml, semantic_model.yml) are written by the generator.
is_dsl() {
    case "$1" in
        */src/main/resources/blueprint/*/*.yml | */src/main/resources/blueprint/*/*.yaml) return 0 ;;
    esac
    return 1
}

# Whether a build script, in the model's module or one above it, declares the
# 3.0 rule engine: an elasticore { } block that sets architecture, language or
# rules. Without it the Gradle plugin runs the 2.x generator.
rule_engine_declared() {
    dir="$1"
    i=0
    while [ -n "$dir" ] && [ "$i" -lt 6 ]; do
        for script in "$dir/build.gradle" "$dir/build.gradle.kts"; do
            if [ -f "$script" ] && grep -q 'elasticore' "$script" 2>/dev/null \
                && grep -Eq '^[[:space:]]*(architecture|language|rules)[[:space:]]*(=|\(|\.)' "$script" 2>/dev/null; then
                return 0
            fi
        done
        parent="$(dirname -- "$dir")"
        [ "$parent" = "$dir" ] && break
        dir="$parent"
        i=$((i + 1))
    done
    return 1
}

# An Edit that only inserts a whole preserved block into a generated file: the
# old text is kept and what is added is one "// !----------" ... "------------!"
# block, which the generator keeps across regeneration.
adds_block() {
    old="$(json_string old_string)"
    new="$(json_string new_string)"
    [ -n "$old" ] || return 1
    rest="${new/"$old"/}"
    [ "$rest" != "$new" ] || return 1
    rest="$(printf '%s' "$rest" | sed -E -e 's/^([[:space:]]|\\[nrt])+//' -e 's/([[:space:]]|\\[nrt])+$//')"
    case "$rest" in
        '// !----------'*'------------!') return 0 ;;
    esac
    return 1
}

# Text for a JSON string: one line, quotes and backslashes escaped.
json_text() {
    printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'
}

# Context for Claude: after a tool ran, or as the reason to go on instead of
# stopping. Unlike exit 2, the transcript shows it as feedback, not an error.
context() {
    printf '{"hookSpecificOutput":{"hookEventName":"%s","additionalContext":"%s"}}\n' "$1" "$(json_text "$2")"
}

# Refuse a tool call; Claude reads the reason.
deny() {
    printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"%s"}}\n' "$(json_text "$1")"
}

# What this session has done, one file per note in the plugin's data directory:
#   dsl-changed-<session>  the DSL changed and no successful generating build followed
#   legacy-noted-<session> the 2.x-generator warning was given
state() {
    base="${CLAUDE_PLUGIN_DATA:-${TMPDIR:-/tmp}/elasticore-agent-kit-$(id -u 2>/dev/null || echo user)}"
    state_dir="$(printf '%s' "$base" | tr '\\' '/')"
    session="$(json_string session_id | tr -cd 'A-Za-z0-9_-')"
    marker="$state_dir/dsl-changed-${session:-default}"
    legacy="$state_dir/legacy-noted-${session:-default}"
}

note() {
    mkdir -p -- "$state_dir" 2>/dev/null && : > "$1"
}

case "$event" in

pre-edit)
    [ "${ELASTICORE_ALLOW_GENERATED_EDITS:-}" = 1 ] && exit 0
    path="$(file_path)"
    case "$path" in
        *.java | *.kt | *.ts | *.tsx | *.proto | *.xml | *.properties | */src/main/resources/blueprint/*) ;;
        *) exit 0 ;;
    esac
    case "$(classify "$path")" in
    managed)
        adds_block && exit 0
        deny "ElastiCORE generates $path from the DSL (its first line is //ecd:). A hand edit is not kept in step: from the next build on, the generator skips the file - SKIP(user-modified) - and it no longer follows the DSL. Make this change in the YAML under src/main/resources/blueprint/<domain>/, or in a file that carries the line '// Initially generated by ElastiCORE;' - the elasticore skill says which. Code that has to live in this very file, such as a custom query in a repository, goes in a preserved block: add one whole block, '// !----------' ... '// ------------!', and nothing else, and only that edit goes through. Do not make the change another way, with Bash or a script. If the user wants this file edited by hand anyway, they can set ELASTICORE_ALLOW_GENERATED_EDITS=1."
        ;;
    regenerated)
        deny "ElastiCORE writes $path again on every generation, so an edit to it is lost. The model is the YAML in src/main/resources/blueprint/<domain>/; a message is translated or reworded in a copy with a locale suffix next to the default file, such as <domain>-messages_ko.properties. Do not make the change another way, with Bash or a script. If the user wants this file edited anyway, they can set ELASTICORE_ALLOW_GENERATED_EDITS=1."
        ;;
    esac
    exit 0
    ;;

pre-bash)
    [ "${ELASTICORE_ALLOW_FORCE:-}" = 1 ] && exit 0
    case "$input" in *-Pforce*) ;; *) exit 0 ;; esac
    command="$(json_string command)"
    printf '%s' "$command" | grep -Eq '(^|[[:space:];&|(/])gradlew?(\.bat)?([[:space:]]|$)' || exit 0
    printf '%s' "$command" | grep -Eq '(^|[[:space:]])-Pforce([[:space:]=]|$)' || exit 0
    deny "-Pforce makes the ElastiCORE generator overwrite hand edits in generated files, and those edits are lost. Ask the user first. If they agree, they can run the command themselves, or set ELASTICORE_ALLOW_FORCE=1."
    exit 0
    ;;

post-edit)
    path="$(file_path)"
    [ -n "$path" ] || exit 0
    model=0
    if is_dsl "$path"; then
        model=1
    else
        case "$path" in
            */build.gradle | */build.gradle.kts) grep -q 'elasticore' "$path" 2>/dev/null && model=1 ;;
        esac
    fi
    if [ "$model" = 1 ]; then
        state
        text=""
        if [ ! -f "$marker" ]; then
            note "$marker"
            text="You changed the ElastiCORE model. Before you finish, run ./gradlew compileJava - it generates first, unless the build sets generateBeforeCompile = false; then run elcore3 or elcore before it - and fix every DSL validation warning and compile error, in the DSL. Read the generator's SKIP(...) lines too. "
        fi
        if is_dsl "$path" && [ ! -f "$legacy" ] \
            && grep -Eq '@(access|owner|password|login|compute|snapshot)([^A-Za-z]|$)|^[[:space:]]*states:|:[[:space:]]*(money|quantity)([^A-Za-z]|$)' "$path" 2>/dev/null \
            && ! rule_engine_declared "${path%%/src/main/resources/blueprint/*}"; then
            note "$legacy"
            text="${text}This project's build has no elasticore { } block that sets architecture, language or rules, so it runs the 2.x generator (elcore). That generator ignores @access, @owner, @password, @login, states:, @compute and @snapshot without a warning, and has no money or quantity types: none of that will be checked, hashed or derived. Tell the user before relying on it; moving the project to the 3.0 rule engine is their decision."
        fi
        [ -n "$text" ] && context PostToolUse "$text"
        exit 0
    fi
    if [ "$(classify "$path")" = block ]; then
        context PostToolUse "$path is generated by ElastiCORE. Only code between '// !----------' and '// ------------!' survives regeneration. A change outside the block is lost on the 2.x generator (elcore) and makes the 3.0 rule engine (elcore3) skip the whole file - put it in the DSL instead."
    fi
    exit 0
    ;;

post-bash)
    case "$input" in *gradle*) ;; *) exit 0 ;; esac
    # Returned before the build ran, or stopped partway: proves nothing.
    json_true run_in_background && exit 0
    json_true interrupted && exit 0
    command="$(json_string command)"
    # A Gradle command whose own task list generates - the task follows gradle
    # or gradlew before any pipe or separator - and that is not a dry run.
    printf '%s' "$command" | grep -Eq '(^|[[:space:];&|(/])gradlew?(\.bat)?[[:space:]]([^|;&]*[[:space:]:])?(elcore[A-Za-z0-9]*|compileJava|compileKotlin|classes|processResources|build|assemble|bootRun|test|check|jar|bootJar)([[:space:]|;&]|$)' || exit 0
    printf '%s' "$command" | grep -Eq '(^|[[:space:]])(--dry-run|-m|help|tasks|--task)([[:space:]]|$)' && exit 0

    # What Gradle printed. The command itself may name the same words (a grep),
    # so only the tool's response counts.
    output="$(printf '%s' "$input" | sed -n 's/.*"tool_response"//p')"
    state
    text=""
    if printf '%s' "$output" | grep -q -F -e 'DSL validation warnings:'; then
        text="The 3.0 rule engine (elcore3) listed DSL validation warnings. The build succeeds anyway, but the model is wrong until they are gone: fix each line under that header in the DSL and build again. "
    fi
    if printf '%s' "$output" | grep -q -F -e '[WARN] DSL Validation Warnings'; then
        text="${text}The 2.x generator (elcore) listed DSL validation warnings and stopped the build: fix each line under that header in the DSL and build again. "
    fi
    if printf '%s' "$output" | grep -q -F -e 'SKIP(user-modified' -e 'Externally Modified Files'; then
        text="${text}The generator found generated files edited by hand and did not update them. If you made those edits in this session, move them into the DSL or into a file you own, then restore each file by deleting it and generating again. If you did not, they are someone's deliberate edits: list them for the user and ask before restoring anything. Never use -Pforce without asking. "
    fi
    if printf '%s' "$output" | grep -q -F -e 'SKIP(no ElastiCORE header'; then
        text="${text}The generator left a file alone because it has no ElastiCORE header, and did not write its own there. If that file was meant to be generated, it has to be deleted and generated again - ask the user if you did not create it."
    fi
    # Cleared only by a build that shows the generator ran and the build passed.
    # A cut or filtered output that lost either line proves nothing.
    if printf '%s' "$output" | grep -q -F -e '=== elcore3: ' -e 'ModelExtractor execution mode' \
        && printf '%s' "$output" | grep -q -F -e 'BUILD SUCCESSFUL' \
        && ! printf '%s' "$output" | grep -q -F -e 'DSL validation warnings:'; then
        rm -f -- "$marker"
    fi
    [ -n "$text" ] && context PostToolUse "$text"
    exit 0
    ;;

stop)
    json_true stop_hook_active && exit 0
    state
    [ -f "$marker" ] || exit 0
    # Remind once per DSL change; the next DSL edit sets the note again.
    rm -f -- "$marker"
    context Stop "The ElastiCORE model changed in this session and no successful Gradle build has generated from it since - a build that failed, ran in the background, or whose output was cut short or filtered does not count. Run ./gradlew compileJava - it generates first - and fix every DSL validation warning and compile error before you finish. If the user asked you not to build, say so in your answer instead."
    exit 0
    ;;

esac
exit 0
